// === Tab: Attractor.js ===
class Attractor {
  constructor (x, y, mass) {
    this.pos = (createVector(x, y));
    this.mass = mass;
    this.r = sqrt(this.mass) * 2;
  }

  show() {
    noStroke();
    fill(255);
    circle(this.pos.x, this.pos.y, this.r*2);
  }

  attract(particle) {
    let force = p5.Vector.sub(this.pos, particle.pos);
    let distanceSq = constrain(force.magSq(), 10, 2);
    //500, 50, (10, 2), (170, 280), (270, 280), (70, 280), (7, 280)
    let G = 10;
    //10, 30, 50

    let strength = G * (this.mass * particle.mass) / distanceSq;

    force.setMag(strength);

    particle.applyForce(force);
  }
}

// === Tab: Particle.js ===
class Particle {
  constructor(x, y, m) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D();
    this.vel.mult(random(1, 5));
    this.acc = createVector(0, 0);
    this.mass = m;
    this.r = sqrt(this.mass)*10;
    this.lifetime = 250;
  }

  show() {
    noStroke();
    fill(255, this.lifetime);
    circle(this.pos.x, this.pos.y, this.r);
    // stroke(255, this.lifetime);
    // line(this.pos.x, this.pos.y, this.pos.x, this.pos.y + 7)
  }

  finished() {
    return this.lifetime < 0;
  }

  applyForce(force) {
    let f = p5.Vector.div(force, this.mass);
    this.acc.add(f);
  }

  edges() {
    if (this.pos.y >=height || this.pos.y <= 0) {
      //this.pos.y = (height - this.size/2);
      this.vel.y *= -1;
    } else if (this.pos.x >= width || this.pos.x <= 0) {
      this.vel.x *= -1;
    }
  }

  go() {
    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.set(0, 0);
    this.lifetime -= 5;
  }
}

// === Tab: System.js ===
class System {
  constructor(x, y) {
    this.position = createVector(x, y);
    this.particles = [];
  }

  emit(num) {
    for (let i = 0; i < num; i++) {
      this.particles.push(new Particle(this.position.x, this.position.y, 0.03));
    }
  }

  update() {
    for (let particle of this.particles) {
      let gravity = createVector(0, -1);
      particle.applyForce(gravity);
      particle.edges();
      particle.go();
      attr.attract(particle);

    }

    for (let i = this.particles.length - 1; i >= 0; i--) {
      if (this.particles[i].finished()) {
        this.particles.splice(i, 1);
      }
    }
  }

  show() {
    for (let particle of this.particles) {
      particle.show();
      //particle.edges();

    }
  }
  }

